// Formateo del estado tributario bajo contrato { ok, data, error }
try {
  const triggerInput = $('Execute Workflow Trigger').first().json;
  const cedulaConsultada = triggerInput.cedula || '';
  const httpRes = $input.first().json;

  const rawBody = httpRes.body !== undefined ? httpRes.body : httpRes;
  const data = Array.isArray(rawBody) ? rawBody[0] : rawBody;

  if (!data || (!data.estadoTributario && !data.moroso)) {
    return [{
      json: {
        ok: true,
        data: {
          cedula: cedulaConsultada,
          estadoTributario: "Desconocido",
          moroso: "DESCONOCIDO",
          motivo: "Cédula no localizada en Hacienda o servicio no concluyente"
        },
        error: null
      }
    }];
  }

  let estadoFinal = "Al dia";
  if (data.moroso === "SI" || data.estadoTributario === "Moroso") {
    estadoFinal = "Moroso";
  }

  return [{
    json: {
      ok: true,
      data: {
        cedula: data.cedula || cedulaConsultada,
        nombre: data.nombre || '',
        estadoTributario: estadoFinal,
        moroso: data.moroso || (estadoFinal === "Moroso" ? "SI" : "NO"),
        situacion: data.situacion || 'Inscrito'
      },
      error: null
    }
  }];
} catch (error) {
  return [{
    json: {
      ok: false,
      data: null,
      error: error.message || 'Error en consulta de Hacienda'
    }
  }];
}
